                 * to complain about */
                if (asn1->name == NULL)
                        return 0;
                sc_debug(ctx, SC_LOG_DEBUG_ASN1, "End of ASN.1 stream, "
                              "non-optional field \"%s\" not found\n",
                              asn1->name);
                return SC_ERROR_ASN1_OBJECT_NOT_FOUND;
        }
        if (p[0] == 0 || p[0] == 0xFF || len == 0)
                return SC_ERROR_ASN1_END_OF_CONTENTS;

