                if (obj == NULL) {
                        sc_debug(ctx, SC_LOG_DEBUG_ASN1, "'%s' not present\n", entry->name);
                        if (choice)
                                continue;
                        if (entry->flags & SC_ASN1_OPTIONAL)
                                continue;
                        sc_debug(ctx, SC_LOG_DEBUG_ASN1, "mandatory ASN.1 object '%s' not found\n", entry->name);
                        if (left) {
                                u8 line[128], *linep = line;
                                size_t i;

