        }
        if (choice && asn1[idx].name == NULL) /* No match */
                SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_ASN1, SC_ERROR_ASN1_OBJECT_NOT_FOUND);
        if (newp != NULL)
                *newp = p;
        if (len_left != NULL)
                *len_left = left;
        if (choice)
                SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_ASN1, idx);
        SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_ASN1, 0);
}

